import { NavBar } from '../pages/nav-bar';
import { LoginPage } from '../pages/login-page';
import { ProductListPage } from '../pages/product-list-page';
import { BasketPage } from '../pages/basket-page';
import {
  DeliveryMethodPage,
  OrderCompletionPage,
  OrderSummaryPage,
  PaymentPage,
  SelectAddressPage,
} from '../pages/checkout-pages';
import { OrderHistoryPage, WalletPage } from '../pages/account-pages';
import { ShopApi } from './shop-api';
import { uniqueEmail } from './test-data';

export type Customer = { email: string; password: string; api: ShopApi };

type Pages = {
  navBar: NavBar;
  loginPage: LoginPage;
  productList: ProductListPage;
  basket: BasketPage;
  selectAddress: SelectAddressPage;
  deliveryMethod: DeliveryMethodPage;
  payment: PaymentPage;
  orderSummary: OrderSummaryPage;
  orderCompletion: OrderCompletionPage;
  orderHistory: OrderHistoryPage;
  wallet: WalletPage;
};

type Fixtures = Pages & {
  /** A new registered customer account with a unique email. Nobody is logged in yet in the browser. */
  customer: Customer;
  /** The same new customer, logged in through the login page. */
  loggedInCustomer: Customer;
};

export const test = base.extend<Fixtures>({
  page: async ({ page, context, baseURL }, use) => {
    // The cookie hides the cookie banner.
    await context.addCookies([{ name: 'cookieconsent_status', value: 'dismiss', url: baseURL! }]);
    await use(page);
  },

  customer: async ({ request }, use, testInfo) => {
    const prefix = testInfo.title.match(/^TC-\d+/)?.[0].toLowerCase() ?? 'customer';
    const email = uniqueEmail(prefix);
    const password = `Passw0rd!${prefix}`;
    const api = new ShopApi(request);
    await api.register(email, password);
    await api.login(email, password);
    await use({ email, password, api });
  },

  loggedInCustomer: async ({ customer, loginPage }, use) => {
    await loginPage.login(customer.email, customer.password);
    await use(customer);
  },

  navBar: async ({ page }, use) => use(new NavBar(page)),
  loginPage: async ({ page }, use) => use(new LoginPage(page)),
  productList: async ({ page }, use) => use(new ProductListPage(page)),
  basket: async ({ page }, use) => use(new BasketPage(page)),
  selectAddress: async ({ page }, use) => use(new SelectAddressPage(page)),
  deliveryMethod: async ({ page }, use) => use(new DeliveryMethodPage(page)),
  payment: async ({ page }, use) => use(new PaymentPage(page)),
  orderSummary: async ({ page }, use) => use(new OrderSummaryPage(page)),
  orderCompletion: async ({ page }, use) => use(new OrderCompletionPage(page)),
  orderHistory: async ({ page }, use) => use(new OrderHistoryPage(page)),
  wallet: async ({ page }, use) => use(new WalletPage(page)),
});

export { expect };
"}

